where state in (1,2,3,4,5,11,22,99)

 and top_name like concat('%', #{topName}, '%')
 and user_name like concat('%', #{userName}, '%')
 and state = #{state}
 and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}

${params.dataScope}
order  by
    case
        when state in (3,5,22) then 1
        when state = 4 then 2
        when state in (1,2,11) then 3
    end,
createtime desc

select #{uid} uid,s.id,u.user_name userName,s.top_number ,d.dept_id,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name, s.top_type,s.party_A,s.party_B, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, s.signing_data, s.validity_Date, concat( s.amount,'万') amount, s.contract, s.filing, s.state from sci_horizontal_apply s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id where s.state = 6
and top_name like concat('%', #{topName}, '%') and user_name like concat('%', #{userName}, '%') and state = #{state} and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}
${params.dataScope} order by createtime desc

select #{uid} uid,s.id,u.user_name userName,s.top_number ,d.dept_id,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name, s.top_type,s.party_A,s.party_B, s.first_person_id, s.second_person_id, s.third_person_id, fourth_person_id, s.signing_data, s.validity_Date, concat( s.amount,'万') amount, s.contract, s.filing, s.state from sci_horizontal_apply s left join sys_user u on s.user_id=u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id =p.dept_id where s.state = 6
and top_name like concat('%', #{topName}, '%') and user_name like concat('%', #{userName}, '%') and state = #{state} and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}
order by createtime desc

select s.id,u.user_name userName, s.user_id, s.top_name,s.top_number , s.top_type,s.party_A,s.party_B,  s.signing_data, s.validity_Date,s.first_person_id,  s.second_person_id, s.third_person_id, s.fourth_person_id,  s.amount, s.contract, s.filing,s.filingurl,s.agreeurl ,s.state
from sci_horizontal_apply s  left join sys_user u on  s.user_id=u.user_id
where s.id = #{id}

